python3 -c "
import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})

# Check qwen14b_dense_baseline for GSM8K details
e = exps.get('qwen14b_dense_baseline', {})
print('=== qwen14b_dense_baseline ===')
for k in ['status','conclusion','metrics','spec','hypothesis']:
    if k in e:
        print(f'  {k}: {e[k]}')

# Check KL s123/s456 GSM8K status
print()
for eid, exp in exps.items():
    if 'qwen14b' in eid and ('s123' in eid or 's456' in eid) and 'gsm8k' in eid.lower():
        print(f'=== {eid} ===')
        for k in ['status','conclusion','metrics','hypothesis']:
            if k in exp:
                print(f'  {k}: {exp[k]}')
        print()

# Also check KL s123/s456 eval experiments for what tasks they covered
print('--- KL s123/s456 eval experiments ---')
for eid, exp in exps.items():
    if 'qwen14b_kl30' in eid and ('s123' in eid or 's456' in eid) and 'eval' in eid:
        print(f'=== {eid} ===')
        for k in ['status','conclusion','metrics','spec']:
            if k in exp:
                val = exp[k]
                if k == 'spec':
                    val = {sk: sv for sk, sv in val.items() if sk in ['eval_data','command']}
                print(f'  {k}: {val}')
        print()
" 2>/dev/null

